mapper.select:
SELECT sg.sku_id, sg.pre_limit_quantity, sg.pre_current_orders, sg.reserved_global,
COALESCE(ss.physical_stock, 0) as physical_stock, COALESCE(ss.reserved_stock, 0) as reserved_stock, (COALESCE(ss.physical_stock, 0) - COALESCE(ss.reserved_stock, 0)) as available_stock, ss.updated_at
COALESCE(sum_ss.total_physical, 0) as physical_stock, COALESCE(sum_ss.total_reserved, 0) as reserved_stock, (COALESCE(sum_ss.total_physical, 0) - COALESCE(sum_ss.total_reserved, 0)) as available_stock, sg.updated_at
FROM sku_global sg
LEFT JOIN sku_stock ss ON sg.sku_id = ss.sku_id AND ss.warehouse_id = #{warehouseId}
LEFT JOIN ( SELECT sku_id, SUM(physical_stock) as total_physical, SUM(reserved_stock) as total_reserved FROM sku_stock GROUP BY sku_id ) sum_ss ON sg.sku_id = sum_ss.sku_id
AND sg.sku_id = #{skuId}
ORDER BY
${sortField} ${sortDirection}
sg.sku_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(sg.sku_id)
FROM sku_global sg


        AND sg.sku_id = #{skuId}

SELECT COUNT(*)
FROM sku_global


        AND sku_id = #{skuId}

SELECT COALESCE(sg.sku_id, sub.sku_id) as skuId, COALESCE(sub.physical_available, 0) as physicalAvailable, COALESCE(sg.pre_limit_quantity, 0) as preLimit, COALESCE(sg.pre_current_orders, 0) as preOrders FROM sku_global sg FULL OUTER JOIN ( SELECT sku_id, SUM(physical_stock - reserved_stock) as physical_available FROM sku_stock
sku_id IN
#{id}
GROUP BY sku_id ) sub ON sg.sku_id = sub.sku_id
COALESCE(sg.sku_id, sub.sku_id) IN
#{id}

mapper.update:
UPDATE sku_global
SET reserved_global = reserved_global - #{quantity},
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE sku_code like #{skuCode}
  AND reserved_global >= #{quantity}

UPDATE sku_stock
SET reserved_stock = reserved_stock - #{quantity},
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE sku_code like #{skuCode}
  AND reserved_global >= #{quantity}
  AND warehouse_id = #{warehouseId}

UPDATE sku_stock
SET physical_stock = physical_stock - #{quantity},
    reserved_stock = reserved_stock - #{quantity},
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE sku_code like #{skuCode}
  AND warehouse_id = #{warehouseId}
  AND physical_stock >= #{quantity}
  AND reserved_stock >= #{quantity}
